            // v1.2.0: what each project is like decides which rule fits it (case ORG-2026-1204, Exhibit 1 and the queue).
            //   open  : must stay open to all 38, so locking out non-payers is exclusion (the court sits on the lot the
            //           town hall offered to all 38; benches, cameras at the entrances and courtyard lights reach everyone)
            //   lock  : non-payers can physically be kept out (a key for the fenced lot or a gate, a Wi-Fi password, a lift key)
            //   group : most of the value sits with one group that can pledge for it (families and older residents for
            //           the park, Block B for its lift, the residents who want cameras)
            //   polar : some residents count it as a harm (cameras and privacy), so the net benefit understates what
            //           its supporters would pledge
            //   clubUse : share of the declared benefit held by the households a club would take in (five high-use
            //           households gave 220 of the 340 euros pledged for the court; the park is a lower-intensity good;
            //           the Wi-Fi and the lift are used by those who would pay for them)
            this.PROJECTS = [
                { id: 'bball',  nameKey: 'proj_bball_name',  descKey: 'proj_bball_desc',  cost: 1200, wtpAnnual: 2400, medianBenefit: 63,  open: true,  lock: true,  group: false, polar: false, clubUse: 0.45 },
                { id: 'park',   nameKey: 'proj_park_name',   descKey: 'proj_park_desc',   cost: 1500, wtpAnnual: 1800, medianBenefit: 47,  open: true,  lock: true,  group: true,  polar: false, clubUse: 0.25 },
                { id: 'wifi',   nameKey: 'proj_wifi_name',   descKey: 'proj_wifi_desc',   cost: 2000, wtpAnnual: 3000, medianBenefit: 79,  open: false, lock: true,  group: false, polar: false, clubUse: 0.9 },
                { id: 'lift',   nameKey: 'proj_lift_name',   descKey: 'proj_lift_desc',   cost: 5000, wtpAnnual: 4500, medianBenefit: 118, open: false, lock: true,  group: true,  polar: false, clubUse: 0.9 },
                { id: 'cams',   nameKey: 'proj_cams_name',   descKey: 'proj_cams_desc',   cost: 3500, wtpAnnual: 3200, medianBenefit: 84,  open: true,  lock: false, group: true,  polar: true,  clubUse: 0.4 },
                { id: 'lights', nameKey: 'proj_lights_name', descKey: 'proj_lights_desc', cost: 600,  wtpAnnual: 900,  medianBenefit: 24,  open: true,  lock: false, group: false, polar: false, clubUse: 0.3 }
