                    trust: 50,
                    cumulativeWelfare: 0,
                    projectsFunded: 0,
                    projectsAttempted: 0,
                    avgEquity: 0,
                    equitySum: 0,
                    equityCost: 0,
                    wtpAttempted: 0,
                    trustHistory: [50],
                    welfareHistory: []
                };
