        _wireMechanismExplain() {
            var sel = document.getElementById('mechanismInput');
            var box = document.getElementById('mechanismExplainText');
            if (!sel || !box) return;
            var update = function() {
                var key = 'mech_help_' + sel.value;
                box.setAttribute('data-i18n', key);
                if (window.mySimulation && window.mySimulation.t) {
