        _currentProject(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.PROJECTS.length - 1);
            return this.PROJECTS[idx];
        }

        _updateBriefing(state) {
            var project = this._currentProject(state);
            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };

            var nameEl = document.getElementById('projectName');
            var descEl = document.getElementById('projectDescription');
            var costEl = document.getElementById('projectCost');
            var wtpEl  = document.getElementById('projectWtp');
            var medEl  = document.getElementById('projectMedian');
            var fairEl = document.getElementById('projectFair');

            if (nameEl) nameEl.textContent = t(project.nameKey);
            if (descEl) descEl.textContent = t(project.descKey);
            if (costEl) costEl.textContent = '€' + project.cost.toLocaleString();
            if (wtpEl)  wtpEl.textContent  = '€' + project.wtpAnnual.toLocaleString();
            if (medEl)  medEl.textContent  = '€' + project.medianBenefit + ' / yr';
            if (fairEl) fairEl.textContent = '€' + Math.ceil(project.cost / this.HOUSEHOLDS);
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);

            var mech = document.getElementById('mechanismInput');
            var comm = document.getElementById('commInput');

            if (mech) decisions.mechanism = mech.value;
            if (comm) decisions.communication = parseInt(comm.value, 10);

            var validMechs = ['voluntary', 'threshold', 'tax', 'club'];
            if (validMechs.indexOf(decisions.mechanism) === -1) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_mechanism'), 'warning'
                );
                return false;
            }
            if (!decisions.communication || decisions.communication < 1 || decisions.communication > 5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_comm'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var project = this._currentProject(state);
            var trust = state.domainState.trust;
            var ds = state.domainState;

            var trustMult = 0.55 + (trust / 100);
            var commMult  = 0.7 + (d.communication * 0.06);

            var funded = false;
            var totalCollected = 0;
            var payers = 0;
            var freeRiders = 0;
            var top5Share = 0;
            var equityScore = 0;
            var welfareGain = 0;
            var trustDelta = 0;
            var narrativeKey = 'narr_default';

            var fairShare = project.cost / this.HOUSEHOLDS;

            // v1.2.0: each rule now works or fails on the features of the project (see PROJECTS), so no rule wins
            // everywhere. Before, the vote passed even where the median household valued the project below its share,
            // and the club was built and scored as full provision on every project.
            if (d.mechanism === 'voluntary') {
                // a sealed box raises what the willing give: the chat pledged 340 euros in eleven weeks for the court
                // with no campaign (case). Enough for a small project, never for the big ones.
                var partRate = Math.min(0.95, 0.30 * trustMult * commMult);
                payers = Math.round(this.HOUSEHOLDS * partRate);
                totalCollected = Math.round(340 * (1 + 0.4 * (d.communication - 1)) * (0.5 + trust / 100));
                freeRiders = this.HOUSEHOLDS - payers;
                top5Share = 0.65;
                equityScore = Math.round(100 - top5Share * 100);
                funded = totalCollected >= project.cost;
                if (funded) {
                    welfareGain = project.wtpAnnual;
                    trustDelta = 5;
                    narrativeKey = 'narr_vol_funded';
                } else {
                    welfareGain = 0;
                    trustDelta = -6;
                    narrativeKey = 'narr_vol_failed';
                }
            }
            else if (d.mechanism === 'threshold') {
                // pledges reach the cost when a group that values the project carries it; a project valued thinly
                // by everyone reaches it only when its benefit is about twice its cost
                var reachBase = project.polar ? 1.15 : (project.group ? 0.8 : 0.45);
                var reach = (project.wtpAnnual / project.cost) * reachBase + 0.05 * (d.communication - 3) + 0.002 * (trust - 50);
                payers = Math.round(this.HOUSEHOLDS * Math.min(0.9, (project.group ? 0.4 : 0.55) + 0.04 * (d.communication - 3)));
                top5Share = 0.50;
                equityScore = Math.round(100 - top5Share * 100);
                funded = reach >= 0.9;
                if (funded) {
                    totalCollected = project.cost;
                    welfareGain = project.wtpAnnual;
                    trustDelta = project.polar ? 2 : (project.group ? 4 : 1);
                    narrativeKey = 'narr_thr_funded';
                } else {
                    totalCollected = 0;
                    welfareGain = 0;
                    trustDelta = -5;
                    narrativeKey = 'narr_thr_failed';
                }
                freeRiders = this.HOUSEHOLDS - payers;
            }
            else if (d.mechanism === 'tax') {
                // median voter: the levy passes when the median household values the project above its equal share
                var perHousehold = project.cost / this.HOUSEHOLDS;
                var supportFactor = (project.medianBenefit / Math.max(1, perHousehold));
                var voteRate = 0.5 + 0.9 * (supportFactor - 1) + 0.02 * (d.communication - 3) + 0.002 * (trust - 50);
                voteRate = Math.min(0.97, Math.max(0.10, voteRate));
                var yesVotes = Math.round(this.HOUSEHOLDS * voteRate);
                funded = yesVotes >= 20;
                top5Share = 5 / this.HOUSEHOLDS;
                equityScore = Math.round(100 - top5Share * 100);
                if (funded) {
                    payers = this.HOUSEHOLDS;
                    totalCollected = project.cost;
                    welfareGain = project.wtpAnnual;
                    freeRiders = 0;
                    // every levy costs trust with the households it overrules: more no-voters, more cost; more again
                    // when it charges everyone for what its users could pay for, or for one group, or for a harm
                    trustDelta = 1 - Math.round(12 * (1 - voteRate)) - (project.open ? 0 : 4) - (project.group ? 2 : 0) - (project.polar ? 4 : 0);
                    narrativeKey = 'narr_tax_passed';
                } else {
                    payers = 0;
                    totalCollected = 0;
                    welfareGain = 0;
                    freeRiders = 0;
                    trustDelta = -4;
                    narrativeKey = 'narr_tax_failed';
                }
            }
            else {
                var clubSize = Math.max(8, Math.round(12 + d.communication - 3));
                clubSize = Math.min(this.HOUSEHOLDS, clubSize);
                top5Share = 5 / clubSize;
                freeRiders = 0;
                if (!project.lock || project.clubUse * project.wtpAnnual * 2 < project.cost) {
                    // no club forms when nothing keeps non-members out (the members would pay for everyone), or when
                    // the heaviest users do not get enough from it to carry the whole cost within two years
                    funded = false;
                    payers = 0;
                    totalCollected = 0;
                    welfareGain = 0;
                    equityScore = 0;
                    trustDelta = -4;
                    narrativeKey = 'narr_club_none';
                } else {
                    funded = true;
                    payers = clubSize;
                    totalCollected = project.cost;
                    equityScore = 60;
                    // welfare counts only the members, who hold clubUse of the declared benefit
                    welfareGain = Math.round(project.wtpAnnual * Math.min(1, project.clubUse * clubSize / 12));
                    if (project.open) {
                        // locked away from neighbours who value it too
                        trustDelta = -6;
                        narrativeKey = 'narr_club';
                    } else {
                        // its users pay and hold the key or the password; those left out valued it little
                        trustDelta = 3;
                        narrativeKey = 'narr_club_fit';
                    }
                }
            }

            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));
            ds.cumulativeWelfare += welfareGain;
            ds.wtpAttempted = (ds.wtpAttempted || 0) + project.wtpAnnual;
            ds.projectsAttempted += 1;
            if (funded) {
                ds.projectsFunded += 1;
                // equity of the money actually raised: cost-weighted over funded projects
                ds.equitySum += equityScore * project.cost;
                ds.equityCost = (ds.equityCost || 0) + project.cost;
            }
            ds.avgEquity = ds.equityCost ? Math.round(ds.equitySum / ds.equityCost) : 0;
            ds.trustHistory.push(ds.trust);
            ds.welfareHistory.push(welfareGain);

            // v1.1.0 FIX: persist a normalized 0-100 score so the instructor results
            // panel (results_utils.php express_resolveDomainScore -> domainState.
            // performance.overallScore) shows a real score instead of "-". Additive;
            // provision/equity/trust mechanics are unchanged.
            ds.performance = {
                overallScore: this._computeScore(ds),
                provision: (ds.projectsAttempted ? Math.round(100 * ds.projectsFunded / ds.projectsAttempted) : 0),
                finalTrust: Math.round(ds.trust),
                avgEquity: ds.avgEquity
            };

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 400);

            return {
                period: state.currentPeriod,
                projectName: project.id,
                mechanism: d.mechanism,
                communication: d.communication,
                cost: project.cost,
                funded: funded,
                fundedLabel: funded ? 'YES' : 'NO',
                totalCollected: totalCollected,
                payers: payers,
                freeRiders: freeRiders,
                equityScore: equityScore,
                welfareGain: welfareGain,
                trustDelta: trustDelta,
                trustAfter: ds.trust,
                narrativeKey: narrativeKey
            };
        }

        _computeScore(ds) {
            // Composite 0-100 over the four numbers the case calls the council record:
            // provision (funded ratio) 35, cumulative welfare (share of the declared benefit delivered to households
            // who can use it) 20, trust 25, equity 20. v1.2.0 adds welfare: without it a club locked away from most of
            // the block scored as full provision.
            var attempted = ds.projectsAttempted || 0;
            var provisionRatio = attempted ? (ds.projectsFunded / attempted) : 0;
            var welfareRatio = ds.wtpAttempted ? Math.min(1, (ds.cumulativeWelfare || 0) / ds.wtpAttempted) : 0;
            var trust = Math.max(0, Math.min(100, ds.trust || 0));
            var equity = Math.max(0, Math.min(100, ds.avgEquity || 0));
            var raw = (provisionRatio * 35) + (welfareRatio * 20) + (trust / 100 * 25) + (equity / 100 * 20);
            return Math.round(Math.max(0, Math.min(100, raw)));
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');

            uiManager.bind('trustDisplay', 'domainState.trust',
                (v) => Math.round(v));
