        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = (window.mySimulation && window.mySimulation.state)
                ? window.mySimulation.state.domainState : {};
            var totalWelfare = ds.cumulativeWelfare || 0;
            var funded = ds.projectsFunded || 0;
            var attempted = ds.projectsAttempted || history.length;
            var trust = Math.round(ds.trust || 0);
            var avgEquity = ds.avgEquity || 0;

            var insights = [];

            var counts = { voluntary: 0, threshold: 0, tax: 0, club: 0 };
            history.forEach(function(h) {
                var m = h.results && h.results.mechanism;
                if (m && counts.hasOwnProperty(m)) counts[m]++;
            });

            if (counts.voluntary >= 3 && funded < attempted * 0.5) {
                insights.push(window.mySimulation.t('insight_voluntary_heavy'));
            }
            if (counts.tax >= 4) {
                insights.push(window.mySimulation.t('insight_tax_heavy'));
            }
            if (counts.club >= 3) {
                insights.push(window.mySimulation.t('insight_club_heavy'));
            }
            var rulesUsed = Object.keys(counts).filter(function(k) { return counts[k] > 0; }).length;
