            }
            if (insights.length === 0) {
                insights.push(window.mySimulation.t('insight_default'));
            }

            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); } : function(k) { return k; };
            var performance = t('rating_beginner');
            if (funded >= attempted * 0.6 && trust >= 40) performance = t('rating_good');
            if (funded >= attempted * 0.8 && trust >= 55 && avgEquity >= 50) performance = t('rating_excellent');

            return {
                overallScore: this._computeScore(ds),
                totalWelfare: totalWelfare,
                projectsFunded: funded,
                projectsAttempted: attempted,
                finalTrust: trust,
                avgEquity: avgEquity,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            summary = summary || {};
            var score = (summary.overallScore != null) ? summary.overallScore : null;
            var funded = (summary.projectsFunded != null) ? summary.projectsFunded : 0;
            var attempted = (summary.projectsAttempted != null) ? summary.projectsAttempted : 0;
            var trust = (summary.finalTrust != null) ? summary.finalTrust : 0;
            var equity = (summary.avgEquity != null) ? summary.avgEquity : 0;
            var welfare = (summary.totalWelfare != null) ? summary.totalWelfare : 0;
            var rating = summary.performance || '';
            var insights = Array.isArray(summary.insights) ? summary.insights : [];
            var items = insights.map(function(s) { return '<li>' + s + '</li>'; }).join('');
            var scoreBlock = (score != null)
                ? '<div class="acacias-completion-score"><span class="acs-num">' + score
                    + '</span><span class="acs-max">/100</span><div class="acs-cap">'
                    + t('complete_score') + '</div></div>'
                : '';
            return ''
                + '<div class="acacias-completion">'
                +   '<h3 class="acacias-completion-title">' + t('complete_title') + '</h3>'
                +   scoreBlock
                +   '<div class="acacias-completion-kpis">'
                +     '<div class="ack"><div class="ack-label">' + t('complete_provision')
                +       '</div><div class="ack-value">' + funded + ' / ' + attempted + '</div></div>'
                +     '<div class="ack"><div class="ack-label">' + t('complete_trust')
                +       '</div><div class="ack-value">' + Math.round(trust) + '</div></div>'
                +     '<div class="ack"><div class="ack-label">' + t('complete_equity')
                +       '</div><div class="ack-value">' + (equity ? equity + ' / 100' : '—') + '</div></div>'
                +     '<div class="ack"><div class="ack-label">' + t('complete_welfare')
                +       '</div><div class="ack-value">€' + Math.round(welfare).toLocaleString() + '</div></div>'
                +   '</div>'
                +   (rating ? '<p class="acacias-completion-rating"><strong>' + t('complete_rating')
                        + ':</strong> ' + rating + '</p>' : '')
                +   (items ? '<div class="acacias-completion-takeaways"><h4>' + t('complete_takeaways')
                        + '</h4><ul>' + items + '</ul></div>' : '')
                +   '<p class="acacias-completion-thanks">' + t('complete_thanks') + '</p>'
                + '</div>';
        }

